@* ───── Security Section ───── *@
@{
    RenderFragment RenderSecurity() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="chevron @(_passwordPanelOpen ? "open" : "")">▶</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <div class="field-error">@_passwordError</div>
                        }
                        <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@_saving">
                            @(_saving ? "Updating..." : "Update Password")
                        </button>
                    </div>
                }
            </div>

            <div class="toggle-row tfa-row">
                <div>
                    <span>Two-Factor Authentication</span>
                    <span class="status-badge @(_twoFactorEnabled ? "enabled" : "disabled")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="slider"></span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange is not null)
            {
                <p class="meta-info">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h4>Active Sessions</h4>
            <div class="table-responsive">
                <table class="table sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (_sessions is not null)
                        {
                            @foreach (var session in _sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _sessions.FirstOrDefault()?.Id)
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => PromptRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            @if (_sessionToRevoke is not null)
            {
                <div class="modal-backdrop" @onclick="() => _sessionToRevoke = null">
                    <div class="confirm-dialog" @onclick:stopPropagation>
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                        <div class="button-row">
                            <button class="btn btn-danger" @onclick="ConfirmRevokeSession" disabled="@_saving">Yes, Revoke</button>
                            <button class="btn btn-secondary" @onclick="() => _sessionToRevoke = null">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };
}

@* ───── Appearance Section ───── *@
@{
    RenderFragment RenderAppearance() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var t = theme;
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@t"
                                   checked="@(_appTheme == t)"
                                   @onchange="() => _appTheme = t" />
                            <span>@t</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var s = size;
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@s"
                                   checked="@(_appFontSize == s)"
                                   @onchange="() => _appFontSize = s" />
                            <span>@s</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" class="form-control" @bind="_appLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Portuguese">Portuguese</option>
                </select>
            </div>

            <div class="toggle-row">
                <span>Compact Mode</span>
                <label class="switch">
                    <input type="checkbox" @bind="_appCompactMode" />
                    <span class="slider"></span>
                </label>
            </div>

            <h4>Live Preview</h4>
            <div class="live-preview @(_appTheme.ToLowerInvariant()) @(_appCompactMode ? "compact" : "")"
                 style="font-size: @GetPreviewFontSize()">
                <div class="preview-header">Settings Dashboard</div>
                <p class="preview-body">
                    This is a preview of your selected appearance settings.
                    Theme: <strong>@_appTheme</strong> · Font: <strong>@_appFontSize</strong> ·
                    Language: <strong>@_appLanguage</strong> · Compact: <strong>@(_appCompactMode ? "On" : "Off")</strong>
                </p>
                <div class="preview-controls">
                    <button class="preview-btn">Sample Button</button>
                    <span class="preview-link">Sample Link</span>
                </div>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
                </button>
            </div>
        </section>
    };
}

@code {
    // ── Navigation ──
    private string ActiveSection { get; set; } = "profile";

    private record SectionDef(string Key, string Label, string Icon);

    private static readonly SectionDef[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨"),
    ];

    // ── State flags ──
    private bool _loading = true;
    private bool _saving;
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // ── Profile state ──
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // ── Notification state ──
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifDigest;
    private HashSet<string> _mutedChannels = [];
    private readonly string[] _allChannels = ["announcements", "marketing", "social", "engineering", "general"];

    // ── Security state ──
    private SecuritySettings? _securitySettings;
    private List<ActiveSession>? _sessions;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private ActiveSession? _sessionToRevoke;

    // ── Appearance state ──
    private string _appTheme = "Light";
    private string _appFontSize = "Medium";
    private string _appLanguage = "English";
    private bool _appCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        var profile = profileTask.Result;
        _savedProfile = profile;
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;

        var notif = notifTask.Result;
        _notifEmail = notif.EmailNotifications;
        _notifPush = notif.PushNotifications;
        _notifDigest = notif.WeeklyDigest;
        _mutedChannels = [.. notif.MutedChannels];

        _securitySettings = securityTask.Result;
        _sessions = [.. _securitySettings.Sessions];
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        var appearance = appearanceTask.Result;
        _appTheme = appearance.Theme;
        _appFontSize = appearance.FontSize;
        _appLanguage = appearance.Language;
        _appCompactMode = appearance.CompactMode;
    }

    // ── Profile actions ──
    private async Task SaveProfile()
    {
        _saving = true;
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _saving = false;
        await ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is null) return;
        _profileDisplayName = _savedProfile.DisplayName;
        _profileEmail = _savedProfile.Email;
        _profileAvatarUrl = _savedProfile.AvatarUrl;
        _profileBio = _savedProfile.Bio;
    }

    // ── Notification actions ──
    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _saving = true;
        var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifDigest, [.. _mutedChannels]);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        await ShowToast("Notification preferences saved.");
    }

    // ── Security actions ──
    private async Task UpdatePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (_newPassword.Length < 6)
        {
            _passwordError = "New password must be at least 6 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        _saving = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _saving = false;
        _passwordPanelOpen = false;
        await ShowToast("Password updated successfully.");
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        _saving = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions = _sessions?.Where(s => s.Id != _sessionToRevoke.Id).ToList();
        _sessionToRevoke = null;
        _saving = false;
        await ShowToast("Session revoked.");
    }

    // ── Appearance actions ──
    private async Task SaveAppearance()
    {
        _saving = true;
        var settings = new AppearanceSettings(_appTheme, _appFontSize, _appLanguage, _appCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        await ShowToast("Appearance settings saved.");
    }

    private string GetPreviewFontSize() => _appFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem",
    };

    // ── Helpers ──
    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }
}
